  "6DGS": { abstractEn: "6-DoF Gaussian Splatting: explicit orientation-aware primitive with full 6D pose parameterization [Abstract pending — contribution details to be added]", abstractCn: "6自由度高斯溅射：显式朝向感知基元，完整6D位姿参数化。 [摘要待补充——贡献详情待添加]" },
  "DisC-GS": { abstractEn: "Progressive low-pass + discontinuity boundary detection preventing splat artifacts at edges [Abstract pending — contribution details to be added]", abstractCn: "渐进式 low-pass + discontinuity boundary detection preventing splat artifacts at edges。 [摘要待补充——贡献详情待添加]" },
  "GaussianImage": { abstractEn: "2D Gaussian image codec at 1000+ FPS [Abstract pending — contribution details to be added]", abstractCn: "2D Gaussian image 编解码器 at 1000+ FPS。 [摘要待补充——贡献详情待添加]" },
  "GES": { abstractEn: "Generalized Exponential Splatting: generalized exponential family replacing Gaussian for flexible primitive shapes [Abstract pending — contribution details to be added]", abstractCn: "Generalized Exponential 溅射: generalized exponential family 替代 Gaussian 用于 flexible primitive shapes。 [摘要待补充——贡献详情待添加]" },
  "Mip-Splatting": { abstractEn: "Mip-Splatting tackles aliasing artifacts in 3D Gaussian Splatting caused by the lack of anti-aliasing mechanisms during rasterization. It applies 3D position smoothing to regularize Gaussian sizes based on local density, then introduces a 2D Mip filter derived from EWA splatting theory to suppress high-frequency noise at varying distances. A scale-aware densification strategy further improves detail preservation at multiple resolution levels. The approach significantly reduces flickering and texture blurring in rendered novel views while maintaining real-time performance.", abstractCn: "Mip-Splatting解决了3D高斯溅射中因光栅化过程缺乏抗锯齿机制导致的混叠伪影。它通过3D位置平滑根据局部密度正则化高斯尺寸，随后引入基于EWA溅射理论的2D Mip滤波器来抑制不同距离下的高频噪声。尺度感知的致密化策略进一步改善了多分辨率层级下的细节保持。该方法显著减少了新视角渲染中的闪烁和纹理模糊，同时保持实时性能。" },
  "Normal-GS": { abstractEn: "Normal-involved rendering: normal constraint + differentiable normal guiding splat distribution [Abstract pending — contribution details to be added]", abstractCn: "法线参与渲染：法线约束+可微法线引导溅射分布。 [摘要待补充——贡献详情待添加]" },
  "ODGS": { abstractEn: "Spherical projection + panoramic camera GS rasterization adaptation for 360-degree images [Abstract pending — contribution details to be added]", abstractCn: "球面投影+全景相机GS光栅化适配用于360度图像。 [摘要待补充——贡献详情待添加]" },
  "3DGS": { abstractEn: "3D Gaussian Splatting introduces anisotropic 3D Gaussians as a direct radiance field representation, avoiding the costly ray-marching required by NeRF. It employs a tile-based differentiable rasterization pipeline with GPU-friendly alpha-compositing for efficient novel view synthesis. Adaptive density control splits and prunes Gaussians during training to progressively refine scene geometry. The method achieves real-time rendering at over 100 FPS while matching or exceeding NeRF's visual quality on standard benchmarks.", abstractCn: "3D高斯溅射引入各向异性3D高斯作为直接辐射场表示，避免了NeRF所需的高代价光线步进。它采用基于瓦片的可微光栅化管线，配合GPU友好的alpha合成实现高效的新视角合成。自适应密度控制在训练过程中分裂和修剪高斯，逐步优化场景几何。该方法在标准基准上实现了超过100 FPS的实时渲染，同时视觉质量匹配或超越NeRF。" },
  "AdaGScale": { abstractEn: "Viewpoint-adaptive Gaussian scaling reducing gaussian-tile pairs for rendering acceleration [Abstract pending — contribution details to be added]", abstractCn: "Viewpoint-自适应 Gaussian scaling reducing gaussian-tile pairs 用于 渲染 加速。 [摘要待补充——贡献详情待添加]" },
