  "FlashWorld": { abstractEn: "FlashWorld presents a feed-forward 3DGS world model that generates dynamic 3D scenes in a single forward pass, enabling real-time interactive world generation without per-scene optimization.", abstractCn: "FlashWorld提出前馈式3DGS世界模型，单次前向推理生成动态3D场景，实现无需逐场景优化的实时交互式世界生成。" },
  "GWM": { abstractEn: "GWM introduces 3D Gaussian Splatting as environment dynamics modeling primitives in a world model framework, enabling autoregressive future state prediction and interactive world simulation through Gaussian-based state transitions.", abstractCn: "GWM将3D高斯泼溅作为环境动力学建模原语引入世界模型框架，实现自回归未来状态预测和基于高斯状态转换的交互式世界模拟。" },
