  "S²AM3D": { abstractEn: "", abstractCn: "" },
  "ArtMesh": { abstractEn: "ArtMesh reconstructs articulated objects as connected triangle meshes with per-part rigid motion, using restricted Delaunay remeshing and bidirectional motion consistency. Introduces the Articulate-100 benchmark with 100 objects across 16 categories.", abstractCn: "ArtMesh以连接三角网格重建铰接物体，采用受限Delaunay重网格化和双向运动一致性约束，提出Articulate-100基准（100物体/16类）。" },
  "CapTalk": { abstractEn: "CapTalk enables text-guided stylization + speech-driven 3D head animation with separate style and emotion control channels.", abstractCn: "CapTalk实现文本风格化+语音驱动3D头像动画，具备独立风格和情感控制通道。" },
  "COSY": { abstractEn: "", abstractCn: "" },
  "D-Rex": { abstractEn: "Diffusion post-process relighting for expressive avatars [Abstract pending — contribution details to be added]", abstractCn: "扩散 post-process 重光照 用于 expressive avatars。 [摘要待补充——贡献详情待添加]" },
  "FlexiAvatar": { abstractEn: "FlexiAvatar is a unified avatar framework that optimizes only visible body regions using SMPL-X tracking and diffusion-based completion, enabling high-fidelity animatable human reconstruction from sparse views. ECCV 2026.", abstractCn: "FlexiAvatar是统一头像框架，利用SMPL-X追踪和扩散补全仅优化可见身体区域，从稀疏视角实现高保真可动画人体重建。ECCV 2026。" },
  "HairGPT": { abstractEn: "Strand-as-Language autoregressive modeling for 3D hairstyle synthesis [Abstract pending — contribution details to be added]", abstractCn: "Strand-as-Language autoregressive modeling 用于 3D hairstyle synthesis。 [摘要待补充——贡献详情待添加]" },
  "High-Fidelity Human GS": { abstractEn: "SMPL-X geometric priors + region-aware initialization [Abstract pending — contribution details to be added]", abstractCn: "SMPL-X geometric priors + region-aware initialization。 [摘要待补充——贡献详情待添加]" },
  "HumanSplatHMR": { abstractEn: "Joint pose refinement + Gaussian avatar optimization [Abstract pending — contribution details to be added]", abstractCn: "联合 pose refinement + Gaussian 头像 优化。 [摘要待补充——贡献详情待添加]" },
  "Latent Dynamics": { abstractEn: "Latent Dynamics introduces a pose-driven 3DGS avatar with dynamics residual latent space, using learned force decomposition for physics-based clothing animation that generalizes across poses.", abstractCn: "Latent Dynamics提出姿态驱动的3DGS头像配合动力学残差隐空间，利用学习力分解实现物理服装动画，可泛化至不同姿态。" },
  "Multi-view Consistent 3D Gaussian Head Avatars": { abstractEn: "", abstractCn: "" },
  "PEAR": { abstractEn: "", abstractCn: "" },
  "PiG-Avatar": { abstractEn: "PiG-Avatar constructs hierarchical neural-field-guided Gaussian avatars in a volumetric canonical space that is decoupled from template topology, enabling high-fidelity avatar reconstruction and animation.", abstractCn: "PiG-Avatar在体素规范空间中构建层次化神经场引导的高斯头像，与模板拓扑解耦，实现高保真头像重建与动画。" },
  "ProgressiveAvatars": { abstractEn: "Progressive animatable 3D Gaussian avatar generation [Abstract pending — contribution details to be added]", abstractCn: "渐进式 可动画化 3D Gaussian 头像 生成。 [摘要待补充——贡献详情待添加]" },
