  "GaussianTalker": { abstractEn: "Audio-driven Gaussian talking head with facial prior and emotion control [Abstract pending — contribution details to be added]", abstractCn: "Audio-driven Gaussian talking head 结合 facial prior and emotion control。 [摘要待补充——贡献详情待添加]" },
  "SplatFace": { abstractEn: "Face-specific GS with identity-preserving Gaussian anchoring from single image [Abstract pending — contribution details to be added]", abstractCn: "Face-specific GS 结合 identity-preserving Gaussian anchoring 从 single image。 [摘要待补充——贡献详情待添加]" },
  "SplatPose": { abstractEn: "Pose-conditioned Gaussian Splatting for monocular human reconstruction [Abstract pending — contribution details to be added]", abstractCn: "Pose-conditioned Gaussian 溅射 用于 单目 human 重建。 [摘要待补充——贡献详情待添加]" },
  "SplatTalk": { abstractEn: "Audio-driven 3D talking face GS with emotion and style control [Abstract pending — contribution details to be added]", abstractCn: "Audio-driven 3D talking face GS 结合 emotion and style control。 [摘要待补充——贡献详情待添加]" },
  "3DGS-Avatar": { abstractEn: "3DGS-Avatar reconstructs animatable human avatars from monocular video by learning pose-conditioned deformation fields that warp a canonical-space Gaussian representation into observed poses. It trains a deformation MLP that maps pose codes to per-Gaussian offsets, rotations, and scale adjustments, enabling generalization to unseen poses at inference. The approach achieves competitive avatar quality with significantly faster training and rendering compared to NeRF-based avatar methods.", abstractCn: "3DGS-Avatar通过学习姿态条件变形场将规范空间的高斯表示扭曲为观察到的姿态，从单目视频重建可动画化的人体头像。它训练变形MLP将姿态编码映射到每个高斯的偏移、旋转和缩放调整，在推理时泛化到未见姿态。该方法相比基于NeRF的头像方法实现了具有竞争力的头像质量，同时训练和渲染显著更快。" },
  "ExpressiveGaussianHuman": { abstractEn: "Expression-coefficient-driven Gaussian deformation fields for expressive human avatars [Abstract pending — contribution details to be added]", abstractCn: "表情系数驱动高斯变形场用于表情丰富的人体头像。 [摘要待补充——贡献详情待添加]" },
  "GAGAvatar": { abstractEn: "Generalizable and animatable Gaussian head avatar from monocular video [Abstract pending — contribution details to be added]", abstractCn: "从单目视频生成可泛化可动画的高斯头部头像。 [摘要待补充——贡献详情待添加]" },
  "GAS": { abstractEn: "Compression + caching for real-time avatar rendering [Abstract pending — contribution details to be added]", abstractCn: "压缩 + caching 用于 实时 头像 渲染。 [摘要待补充——贡献详情待添加]" },
  "GauHuman": { abstractEn: "Human-specific GS with SMPL-constrained Gaussian initialization and pose-aware densification [Abstract pending — contribution details to be added]", abstractCn: "人体专属GS，SMPL约束高斯初始化+姿态感知致密化。 [摘要待补充——贡献详情待添加]" },
  "GaussianAvatar": { abstractEn: "GaussianAvatar proposes a pose-driven human body representation where 3D Gaussians are attached to a parametric body model and deform according to pose parameters. Each Gaussian is anchored to a body surface point and displaced via linear blend skinning, enabling fast avatar animation without per-frame optimization. The method produces high-fidelity renderings of human avatars under novel poses while supporting real-time rendering at interactive frame rates.", abstractCn: "GaussianAvatar提出了一种姿态驱动的人体表示，其中3D高斯附着于参数化人体模型并根据姿态参数变形。每个高斯锚定到人体表面点并通过线性混合蒙皮位移，无需逐帧优化即可实现快速虚拟人动画。该方法在新姿态下产生高保真的人体头像渲染，同时支持交互帧率的实时渲染。" },
  "HeadGaS": { abstractEn: "Dynamic head GS with blendshape-driven Gaussian deformation for real-time reenactment [Abstract pending — contribution details to be added]", abstractCn: "动态头部GS，混合变形驱动高斯变形实现实时演绎。 [摘要待补充——贡献详情待添加]" },
  "Human3Diffusion": { abstractEn: "Diffusion + GS dual-driven 3D human avatar reconstruction [Abstract pending — contribution details to be added]", abstractCn: "扩散+GS双驱动3D人体头像重建。 [摘要待补充——贡献详情待添加]" },
  "HumanSplat-NIPS": { abstractEn: "Single-image human GS with SMPL-guided Gaussian binding [Abstract pending — contribution details to be added]", abstractCn: "单图人体GS，SMPL引导高斯绑定。 [摘要待补充——贡献详情待添加]" },
  "SplatArmor": { abstractEn: "SplatArmor represents articulated human bodies by deforming a canonical set of Gaussians through linear blend skinning (LBS) with twist-aware deformation corrections that reduce artifacts near joint regions. The twist-aware formulation mitigates volume loss and interpenetration that standard LBS introduces while preserving articulation fidelity under extreme poses. It demonstrates detailed human body rendering and animation with fewer deformation artifacts than prior Gaussian-based avatar methods.", abstractCn: "SplatArmor通过线性混合蒙皮（LBS）变形规范高斯集合并引入扭曲感知变形校正来表示铰接式人体，减少关节区域附近的伪影。扭曲感知公式减轻了标准LBS引入的体积损失和穿透，同时在极端姿态下保持铰接保真度。它展示了比先前基于高斯的头像方法更少变形伪影的详细人体渲染和动画。" },
  "SplattingAvatar": { abstractEn: "Expression-conditioned Gaussian deformation [Abstract pending — contribution details to be added]", abstractCn: "Expression-conditioned Gaussian 变形。 [摘要待补充——贡献详情待添加]" },
