  "PanoLOG": { abstractEn: "", abstractCn: "" },
  "PatchPoison": { abstractEn: "Poisoning multi-view datasets to degrade 3D reconstruction (Security) [Abstract pending — contribution details to be added]", abstractCn: "Poisoning 多视图 datasets to degrade 3D 重建 (安全)。 [摘要待补充——贡献详情待添加]" },
  "PG-3DGS": { abstractEn: "PG-3DGS couples differentiable physics simulation with 3D Gaussian representations, allowing physical objectives such as stability, collision avoidance, and material consistency to directly guide shape optimization. Gradients from the physics simulator backpropagate through Gaussian parameters, enabling end-to-end training that jointly satisfies visual fidelity and physical constraints. This produces reconstructed scenes where objects obey physical laws, unlike standard 3DGS which only optimizes for photometric consistency.", abstractCn: "PG-3DGS将可微物理模拟与3D高斯表示耦合，允许稳定性、碰撞避免和材质一致性等物理目标直接指导形状优化。来自物理模拟器的梯度反向传播通过高斯参数，实现端到端训练同时满足视觉保真度和物理约束。这产生物体遵循物理定律的重建场景，不同于仅优化光度一致性的标准3DGS。" },
  "RESPIRE": { abstractEn: "CT-informed mesh-anchored GS for dynamic bronchoscopy [Abstract pending — contribution details to be added]", abstractCn: "CT-informed 网格-anchored GS 用于 动态 bronchoscopy。 [摘要待补充——贡献详情待添加]" },
