  "Visionary": { abstractEn: "Visionary is a WebGPU + ONNX Runtime 3DGS world model carrier platform, enabling real-time 4DGS, neural avatars, and generative post-processing directly in the browser for the first time.", abstractCn: "Visionary是基于WebGPU+ONNX Runtime的3DGS世界模型载体平台，首次在浏览器端实现4DGS、神经人像和生成式后处理的实时运行。" },
  "XFreq-GS": { abstractEn: "Cross-frequency wireless radiation field reconstruction with shared geometry + frequency-adaptive RF attributes [Abstract pending — contribution details to be added]", abstractCn: "Cross-frequency wireless radiation field 重建 结合 shared geometry + frequency-自适应 RF attributes。 [摘要待补充——贡献详情待添加]" },
