  "TAIL-Safe": { abstractEn: "Safety monitoring for IL policies using 3DGS digital twin [Abstract pending — contribution details to be added]", abstractCn: "Safety monitoring 用于 IL policies using 3DGS digital twin。 [摘要待补充——贡献详情待添加]" },
  "GS-ID": { abstractEn: "GS-ID performs 3DGS-based real-scene illumination decomposition, providing high-fidelity light field data for embodied intelligence and autonomous driving with relighting-capable Gaussian representations.", abstractCn: "GS-ID实现基于3DGS的真实场景光场分解，为具身智能和自动驾驶提供高保真光场数据和可重光照的高斯表示。" },
  "GS-Physics": { abstractEn: "Physics-integrated GS with differentiable simulation for rigid/soft body dynamics [Abstract pending — contribution details to be added]", abstractCn: "物理-integrated GS 结合 可微 仿真 用于 rigid/soft body dynamics。 [摘要待补充——贡献详情待添加]" },
  "Splat-Nav": { abstractEn: "GS-based navigation with Gaussian-anchored topological maps [Abstract pending — contribution details to be added]", abstractCn: "GS-based navigation 结合 Gaussian-anchored topological maps。 [摘要待补充——贡献详情待添加]" },
  "SplatSim": { abstractEn: "GS-based sim-to-real transfer for robotic manipulation with photorealistic rendering [Abstract pending — contribution details to be added]", abstractCn: "GS-based sim-to-real transfer 用于 机器人 操作 结合 photorealistic 渲染。 [摘要待补充——贡献详情待添加]" },
  "VR-Robo": { abstractEn: "Real-to-Sim-to-Real framework for visual robot navigation and locomotion via 3DGS reconstruction [Abstract pending — contribution details to be added]", abstractCn: "Real-to-Sim-to-Real framework 用于 visual robot navigation and locomotion 通过 3DGS 重建。 [摘要待补充——贡献详情待添加]" },
  "FreeMoCap": { abstractEn: "Open-source markerless motion capture from webcams (AGPL-3.0, 8.3k stars); drives 3DGS avatars; dual-use multi-cam for mocap + 3DGS training.", abstractCn: "Open-source markerless motion capture from webcams (AGPL-3.0, 8.3k stars); drives 3DGS avatars; dual-use multi-cam for mocap + 3DGS training。[摘要待补充——贡献详情待添加]" },
  "GaussianGrasper": { abstractEn: "GaussianGrasper builds a 3D language-embedded Gaussian representation that supports open-vocabulary robotic grasping by distilling SAM segmentation and CLIP semantic features into per-Gaussian embeddings. The fused features enable grounding arbitrary language queries to 3D object regions, which are then passed to a grasp planner for target-driven manipulation. Experiments on real robots show accurate language-conditioned grasping across diverse objects and cluttered scenes.", abstractCn: "GaussianGrasper构建了3D语言嵌入的高斯表示，通过将SAM分割和CLIP语义特征蒸馏到每个高斯的嵌入中来支持开放词汇机器人抓取。融合的特征使任意语言查询能够定位到3D物体区域，然后传递给抓取规划器进行目标驱动的操作。真实机器人实验展示了在多样物体和杂乱场景中准确的语言条件抓取。" },
  "GaussNav": { abstractEn: "GaussNav enables embodied navigation through language-guided semantic Gaussian maps built from 3D Gaussian Splatting representations. The method augments each Gaussian with language grounding features that allow the navigation agent to query and localize semantically meaningful objects described in natural language instructions. A real-time map updating module incrementally adds new Gaussians as the agent explores, maintaining an up-to-date semantic representation of the environment. GaussNav achieves higher success rates in language-guided navigation tasks compared to prior NeRF and point cloud-based approaches on the R2R and REVERIE benchmarks.", abstractCn: "GaussNav通过基于3D高斯泼溅表示构建的语言引导语义高斯地图实现具身导航。该方法为每个高斯附加语言定位特征，使导航智能体能够查询和定位自然语言指令中描述的语义目标。实时地图更新模块在智能体探索过程中增量添加新高斯，维护环境的最新语义表示。在R2R和REVERIE基准上，GaussNav在语言引导导航任务中的成功率高于先前的NeRF和点云方法。" },
  "GIC": { abstractEn: "Gaussian-Informed Continuum for physical property identification and differentiable simulation [Abstract pending — contribution details to be added]", abstractCn: "高斯信息连续体用于物理属性识别与可微仿真。 [摘要待补充——贡献详情待添加]" },
  "GraspSplats": { abstractEn: "Efficient zero-shot manipulation with 3D feature splatting; demonstrates NeRF unsuitable for scene changes [Abstract pending — contribution details to be added]", abstractCn: "高效 零样本 操作 结合 3D 特征 溅射; demonstrates NeRF unsuitable 用于 scene changes。 [摘要待补充——贡献详情待添加]" },
  "ManiGaussian": { abstractEn: "ManiGaussian integrates a dynamic Gaussian world model with robotic manipulation, where 3D Gaussians represent the scene and a learned dynamics module predicts future Gaussian states given robot actions. The world model provides visual imagination of action outcomes, serving as a reward signal and planning aid for multi-task manipulation policies. It improves manipulation success rates across multiple RLBench tasks compared to methods without scene-level prediction.", abstractCn: "ManiGaussian将动态高斯世界模型与机器人操作相结合，其中3D高斯表示场景，学习到的动力学模块根据机器人动作预测未来高斯状态。世界模型提供动作结果的视觉想象，作为多任务操作策略的奖励信号和规划辅助。相比没有场景级预测的方法，它在多个RLBench任务上提高了操作成功率。" },
